package com.adaptivelearning.planning.application;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PlanValidationPolicyTest {private final ZoneId zone=ZoneId.of("Asia/Shanghai");@Test void detectsCapacityOverflow(){LocalDate day=LocalDate.of(2026,7,22);var changes=List.of(change("任务一",day,90),change("任务二",day,60));var issues=PlanValidationPolicy.validate(changes,day.minusDays(1),day.plusDays(1),Map.of(day,120),.85);assertThat(issues).extracting(PlanValidationPolicy.Issue::code).contains("PLAN_CAPACITY_EXCEEDED");}@Test void rejectsLongTask(){LocalDate day=LocalDate.of(2026,7,22);var issues=PlanValidationPolicy.validate(List.of(change("长任务",day,121)),day,day,Map.of(day,300),.85);assertThat(issues).extracting(PlanValidationPolicy.Issue::code).contains("TASK_DURATION_INVALID");}@Test void noCapacityErrorAtExactlyRatio(){LocalDate day=LocalDate.of(2026,7,22);var issues=PlanValidationPolicy.validate(List.of(change("合法任务",day,102)),day,day,Map.of(day,120),.85);assertThat(issues).extracting(PlanValidationPolicy.Issue::code).doesNotContain("PLAN_CAPACITY_EXCEEDED");}private PlanValidationPolicy.Change change(String title,LocalDate d,int min){var s=ZonedDateTime.of(d,LocalTime.of(19,0),zone);return new PlanValidationPolicy.Change("ADD_TASK",title,s,s.plusMinutes(min),min,false,true);}}
